mapper.select:
SELECT 
FROM gt_bond_investment
WHERE org_id = #{orgId}

    AND investment_no LIKE CONCAT('%', #{investmentNo}, '%')


    AND bond_code LIKE CONCAT('%', #{bondCode}, '%')


    AND bond_type = #{bondType}


    AND issuer LIKE CONCAT('%', #{issuer}, '%')


    AND investment_status = #{investmentStatus}

ORDER BY create_time DESC

SELECT 
FROM gt_bond_investment
WHERE investment_no = #{investmentNo} AND org_id = #{orgId}

SELECT COALESCE(SUM(purchase_price * purchase_quantity), 0)
FROM gt_bond_investment
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(current_value), 0)
FROM gt_bond_investment
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(unrealized_gain_loss), 0)
FROM gt_bond_investment
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(accrued_interest), 0)
FROM gt_bond_investment
WHERE org_id = #{orgId}

SELECT COUNT(*)
FROM gt_bond_investment
WHERE investment_no = #{investmentNo} AND org_id = #{orgId}

    AND investment_id != #{excludeId}

SELECT investment_id, investment_no, bond_code, 'NEAR_MATURITY' as alertType, '债券即将到期' as alertMessage, maturity_date as alertDate FROM gt_bond_investment WHERE investment_status = 'ACTIVE' AND maturity_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND org_id = #{orgId}
UNION ALL
SELECT investment_id, investment_no, bond_code, 'COUPON_PAYMENT' as alertType, '债券即将付息' as alertMessage, next_coupon_date as alertDate FROM gt_bond_investment WHERE investment_status = 'ACTIVE' AND next_coupon_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND org_id = #{orgId}
